{"command":"cat > records.py <<'PY'
"""Decoder for the internal ``trk`` telemetry record format.

Capture-derived layout: one-byte type, uint16 little-endian payload length,
payload, then uint32 little-endian CRC32 of the header and payload (seed
0x9c2f41b7). Payload integers are big-endian. Samples contain a uint32 minute
counter, uint24 thousandths value and flags byte. Batches contain a uint16
count, uint16 hundredths values and flags byte.
"""

from datetime import datetime, timedelta, timezone
import zlib


_CRC_SEED = 0x9C2F41B7
_EPOCH = datetime(2000, 1, 2, tzinfo=timezone.utc)
_FLAG_NAMES = ("low_battery", "recal", "stale")


def decode_records(data: bytes) -> list[dict]:
    """Decode a feed, rejecting incomplete frames and invalid checksums."""
    records = []
    offset = 0
    while offset < len(data):
        if len(data) - offset < 3:
            raise ValueError("truncated record header")
        kind = data[offset]
        length = int.from_bytes(data[offset + 1:offset + 3], "little")
        payload_start = offset + 3
        payload_end = payload_start + length
        frame_end = payload_end + 4
        if frame_end > len(data):
            raise ValueError("truncated record payload or checksum")
        checksum = int.from_bytes(data[payload_end:frame_end], "little")
        if zlib.crc32(data[offset:payload_end], _CRC_SEED) != checksum:
            raise ValueError(f"checksum mismatch at offset {offset}")
        payload = data[payload_start:payload_end]
        if kind == 2:
            if length != 8:
                raise ValueError("invalid sample payload length")
            minutes = int.from_bytes(payload[:4], "big")
            record = {
                "type": "sample",
                "ts": (_EPOCH + timedelta(minutes=minutes)).strftime(
                    "%Y-%m-%dT%H:%M:%SZ"
                ),
                "value": int.from_bytes(payload[4:7], "big") / 1000,
            }
        elif kind == 7:
            if length < 3:
                raise ValueError("invalid batch payload length")
            count = int.from_bytes(payload[:2], "big")
            if length != 3 + 2 * count:
                raise ValueError("invalid batch payload length")
            record = {
                "type": "batch",
                "values": [
                    int.from_bytes(payload[i:i + 2], "big") / 100
                    for i in range(2, 2 + 2 * count, 2)
                ],
            }
        else:
            raise ValueError(f"unknown record type {kind}")
        record["flags"] = [
            name for bit, name in enumerate(_FLAG_NAMES)
            if payload[-1] & (1 << bit)
        ]
        records.append(record)
        offset = frame_end
    return records
PY
